<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">chmod</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> u+x</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> script.sh</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">           # 所有者(u)增加执行权限</span></span>
